mapper.sql:
FROM TB_REVIEW_DELETE_REQUEST DR LEFT JOIN TB_REVIEW R ON R.REVIEW_ID = DR.REVIEW_ID AND R.REVIEW_TYPE = DR.REVIEW_TYPE LEFT JOIN TB_MEMBER M ON M.MEMBER_NO = R.MEMBER_NO JOIN TB_HOSPITAL H ON H.HOSPITAL_ID = DR.TARGET_ID JOIN TB_BUSINESS B ON B.BIZ_NO = DR.BIZ_NO WHERE DR.REVIEW_TYPE = 'HOSPITAL'
AND DR.STATUS_CD = #{statusCd}
AND ( H.NAME LIKE '%' || #{keyword} || '%' OR B.BIZ_NAME LIKE '%' || #{keyword} || '%' OR M.NICKNAME LIKE '%' || #{keyword} || '%' OR DR.REQUEST_REASON LIKE '%' || #{keyword} || '%' )

mapper.delete:
DELETE FROM TB_REVIEW
 WHERE REVIEW_ID = #{reviewId}
   AND REVIEW_TYPE = 'HOSPITAL'
